// Arrange
cy.visit('https://www.saucedemo.com/');
//Act login
cy.get('[data-test="username"]').type('standard_user');
cy.get('[data-test="password"]').type('secret_sauce');
cy.get('[data-test="login-button"]').click();
// Adiciona ao carrinho
cy.get('[data-test="inventory-item-name"]').first().invoke('text').then(itemNameToCart => {
  // Adiciona ao carrinho
  cy.get('[data-test^="add-to-cart"]').first().click();
  // Valida badge
  cy.get('.shopping_cart_badge').should('be.visible').and('have.text', '1');
  // Vai para carrinho
  cy.get('#shopping_cart_container').click();
  // Valida URL
  cy.url().should('include', '/cart.html');
  // Valida item correto
  cy.get('[data-test="inventory-item-name"]').should('have.text', itemNameToCart);
  // Remove item
  cy.get('[data-test^="remove"]').first().click();
  cy.contains('[data-test="inventory-item-name"]', itemNameToCart).should('not.exist');
  // Valida badge removido
  cy.get('.shopping_cart_badge').should('not.exist');
});
